*{box-sizing:border-box}
 :root{--ink:#e7e4d7;--muted:#9a9c8b;--dim:#63685d;--acid:#c5d06f;--line:rgba(222,224,193,.16);--panel:rgba(17,21,17,.88);--mono:'DM Mono',monospace;--display:'Barlow Condensed',sans-serif;--sans:'Manrope',sans-serif}
html,body{height:100%;margin:0;background:#111713;color:var(--ink);font-family:var(--sans);overflow:hidden}
button{font:inherit;color:inherit}
#game-shell{position:relative;width:100vw;height:100dvh;min-height:500px;overflow:hidden;background:#182019;isolation:isolate}
#world{position:absolute;inset:0;width:100%;height:100%;display:block}
.vignette,.scanlines{pointer-events:none;position:absolute;inset:0;z-index:1}
.vignette{background:radial-gradient(ellipse at 48% 48%,transparent 42%,rgba(5,9,7,.2) 85%,rgba(5,8,7,.7) 145%)}
.scanlines{opacity:.09;background:repeating-linear-gradient(0deg,transparent 0 2px,rgba(0,0,0,.4) 3px 4px);mix-blend-mode:multiply}
.topbar{height:76px;position:absolute;inset:0 0 auto;z-index:4;display:flex;align-items:center;padding:0 30px;gap:32px;background:linear-gradient(180deg,rgba(10,14,12,.94),rgba(10,14,12,.72));border-bottom:1px solid rgba(226,228,198,.12)}
.brand{display:flex;gap:11px;align-items:center;min-width:225px}
.brand-mark{font:800 21px var(--display);letter-spacing:-1px;border:1px solid #aeb66a;color:#d4d7ae;width:39px;height:39px;display:grid;place-items:center;position:relative}
.brand-mark span{color:#d5a35b}
.brand-title{font:700 19px var(--display);letter-spacing:2px;line-height:1}
.brand-sub{font:9px var(--mono);letter-spacing:1.4px;color:#929789;margin-top:5px}
.brand-sub span{color:#ba9d5a;margin:0 3px}
.weather,.faction-status{height:39px;display:flex;align-items:center;gap:11px;border-left:1px solid var(--line);padding-left:22px}
.weather-icon{font-size:23px;color:#bbc28b}
.weather b,.faction-status b{display:block;font:10px var(--mono);letter-spacing:1.2px;color:#d3d5bd}
.weather small,.faction-status small{display:block;font:9px var(--mono);letter-spacing:.25px;color:#858b7d;margin-top:5px}
.faction-status{margin-left:auto;max-width:310px}
.faction-status i,.live-dot{height:7px;width:7px;border-radius:50%;background:#c9b268;box-shadow:0 0 9px #c9b268;flex:none}
.faction-status small{max-width:240px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.icon-button{width:37px;height:37px;border:1px solid var(--line);background:rgba(255,255,255,.025);font-size:14px;color:#b9c08f;cursor:pointer}
.icon-button:hover{background:#343a29}
.pause-button{font-size:17px}
.hud-card{z-index:3;position:absolute;background:linear-gradient(135deg,rgba(15,20,17,.92),rgba(18,23,19,.78));border:1px solid rgba(215,220,184,.18);box-shadow:0 8px 32px rgba(0,0,0,.2);backdrop-filter:blur(8px)}
.mission-card{top:102px;left:30px;width:285px;padding:17px 18px 14px}
.eyebrow{font:9px var(--mono);letter-spacing:1.4px;color:#c4c58e;display:flex;align-items:center;gap:8px}
.live-dot{width:6px;height:6px}
.task-code{color:#777e6b;margin-left:auto}
.mission-card h1{font:600 25px var(--display);letter-spacing:.3px;margin:12px 0 4px;color:#e3e1ce}
.mission-card p{font-size:10px;line-height:1.7;color:#9da092;margin:0;max-width:240px}
.mission-progress{display:flex;align-items:center;justify-content:space-between;font:9px var(--mono);letter-spacing:.7px;color:#c4c58e;margin-top:17px}
.compass-arrow{font-size:17px;color:#d9bd6d}
.progress-track{height:2px;background:#43483a;margin-top:7px}
.progress-track i{display:block;width:8%;height:100%;background:#c8cd75;transition:width .3s}
.task-state{border-top:1px solid var(--line);padding-top:12px;margin-top:13px;display:flex;align-items:center;gap:9px;font:8px var(--mono);letter-spacing:.7px;color:#c7c9b2}
.task-check{font-size:10px;color:#d1b76a;border:1px solid #77734a;padding:3px 4px}
.task-state-right{margin-left:auto;font-size:8px;color:#a6a87c}
.map-card{top:102px;right:30px;width:252px;padding:13px 14px 12px}
