.toast{position:absolute;z-index:5;top:48%;left:50%;transform:translate(-50%,-50%);background:rgba(12,16,13,.92);border:1px solid rgba(210,205,143,.36);padding:10px 15px;font:10px var(--mono);letter-spacing:.4px;color:#e2dfc6;opacity:0;transition:opacity .2s;pointer-events:none}
