.title-noise{position:absolute;inset:0;background:linear-gradient(90deg,rgba(10,14,12,.75),rgba(10,14,12,.15)),radial-gradient(ellipse at 65% 52%,rgba(112,111,67,.12),transparent 40%),repeating-linear-gradient(135deg,transparent 0 8px,rgba(207,210,171,.018) 9px 10px);pointer-events:none}
