.primary-button{height:48px;min-width:240px;border:1px solid #c1c878;background:#858e4d;color:#10150f;display:flex;align-items:center;justify-content:space-between;padding:0 17px;font:700 11px var(--mono);letter-spacing:1px;cursor:pointer;transition:background .15s,transform .15s}
