/* Android / compact touch HUD */
button{ -webkit-tap-highlight-color:transparent; user-select:none }
@media (pointer:coarse), (max-width:850px){
  #game-shell{min-height:0;touch-action:none}
  .topbar{padding-left:max(10px,env(safe-area-inset-left));padding-right:max(10px,env(safe-area-inset-right))}
  .weather{display:none}
  .mission-card{left:max(8px,env(safe-area-inset-left));top:calc(62px + env(safe-area-inset-top));width:min(54vw,220px);padding:9px 10px}
  .mission-card h1{font-size:17px;margin:5px 0 0}
  .mission-card p,.mission-card .eyebrow,.mission-card .task-state,.mission-card .progress-track{display:none}
  .mission-progress{margin-top:5px;font-size:7px}
  .map-card{right:max(8px,env(safe-area-inset-right));top:calc(62px + env(safe-area-inset-top));width:118px;padding:7px}
  .map-wrap{height:67px;margin-top:5px}
  .map-north,.map-legend{display:none}
  .map-coords{font-size:6px}
  .status-panel{left:max(8px,env(safe-area-inset-left));bottom:calc(124px + env(safe-area-inset-bottom));width:clamp(142px,42vw,190px);padding:7px 9px}
  .status-top{margin-bottom:5px}
  .stat-line{margin:5px 0}
  .status-bottom{padding-top:5px;margin-top:5px}
  .weapon-panel{right:max(8px,env(safe-area-inset-right));bottom:calc(124px + env(safe-area-inset-bottom));width:clamp(130px,38vw,180px);height:57px;padding:6px;gap:4px}
  .weapon-controls{display:none}
  .hotbar,.controls-note{display:none}
  .touch-controls{height:125px;bottom:env(safe-area-inset-bottom);pointer-events:none}
  .stick,.aim-stick{pointer-events:auto;position:absolute;bottom:10px;width:94px;height:94px;border:1px solid rgba(230,232,196,.28);border-radius:50%;background:rgba(15,19,15,.36);touch-action:none}
  .stick{left:max(12px,env(safe-area-inset-left))}
  .aim-stick{right:148px}
  .stick-knob{width:39px;height:39px}
  .touch-actions{pointer-events:auto;position:absolute;right:max(8px,env(safe-area-inset-right));bottom:11px;width:128px;display:grid;grid-template-columns:repeat(3,1fr);gap:4px}
  .touch-actions button{height:40px;min-width:0;padding:0 2px;font:7px var(--mono);border-radius:4px;touch-action:none}
  .touch-actions #touch-fire{grid-row:span 2;height:84px;font-size:9px;background:rgba(108,43,32,.72)}
  #touch-med,#touch-water,#touch-reload{font-size:6px}
  .interaction-prompt{top:48%;max-width:85vw;font-size:8px}
  .toast{top:42%;max-width:90vw;text-align:center}
}
@media (max-width:540px){
  .topbar{height:54px}
  .mission-card,.map-card{top:calc(60px + env(safe-area-inset-top))}
  .mission-card{width:min(52vw,190px)}
  .map-card{width:108px}
  .map-wrap{height:58px}
  .status-panel{bottom:calc(119px + env(safe-area-inset-bottom));width:42vw}
  .weapon-panel{bottom:calc(119px + env(safe-area-inset-bottom));width:39vw}
  .aim-stick{right:143px;width:88px;height:88px}
  .stick{width:88px;height:88px}
  .touch-actions{width:122px}
  .touch-actions button{height:38px}
  .touch-actions #touch-fire{height:80px}
  .touch-controls{height:115px}
}
@media (max-height:520px) and (orientation:landscape){
  .mission-card,.map-card{top:calc(56px + env(safe-area-inset-top))}
  .mission-card{width:190px}
  .map-card{width:100px}
  .map-wrap{height:48px}
  .status-panel,.weapon-panel{bottom:calc(96px + env(safe-area-inset-bottom))}
  .touch-controls{height:92px}
  .stick,.aim-stick{width:70px;height:70px;bottom:6px}
  .stick-knob{width:31px;height:31px}
  .aim-stick{right:143px}
  .touch-actions{bottom:6px}
}

