from http.server import SimpleHTTPRequestHandler, ThreadingHTTPServer
from pathlib import Path
import base64
ROOT=Path('/home/runner/work/PlayGround/PlayGround')
PAGE=Path('/tmp/opencode/render-assets.html')
class Handler(SimpleHTTPRequestHandler):
    def translate_path(self, path):
        if path == '/render-assets.html': return str(PAGE)
        return str(ROOT / path.lstrip('/'))
    def do_POST(self):
        if not self.path.startswith('/save/'):
            self.send_error(404); return
        name=self.path.rsplit('/',1)[-1]
        if name not in {'soldier.png','barracks.png','pine-tree.png'}:
            self.send_error(400); return
        data=self.rfile.read(int(self.headers.get('Content-Length','0'))).decode()
        try: raw=base64.b64decode(data.split(',',1)[1])
        except Exception:
            self.send_error(400); return
        out=ROOT/'public'/'sprites'/name
        out.parent.mkdir(parents=True,exist_ok=True);out.write_bytes(raw)
        self.send_response(201);self.end_headers();self.wfile.write(str(len(raw)).encode())
    def log_message(self, fmt, *args): print(fmt%args, flush=True)
ThreadingHTTPServer(('0.0.0.0',8765),Handler).serve_forever()

